struct ibv_sge sge = { .addr = (uintptr_t)buf, .length = 64, .lkey = mr->lkey };
struct ibv_send_wr wr = {
    .wr_id = 7, .sg_list = &sge, .num_sge = 1,
    .opcode = IBV_WR_SEND, .send_flags = IBV_SEND_SIGNALED };
struct ibv_send_wr *bad;
if (ibv_post_send(qp, &wr, &bad)) die("post");

struct ibv_wc wc;
int n;
do { n = ibv_poll_cq(cq, 1, &wc); } while (n == 0);
if (n < 0 || wc.status != IBV_WC_SUCCESS) die("completion");
/* only now may buf be reused: wc.wr_id == 7 */

struct ibv_sge sge = { .addr = (uintptr_t)buf, .length = 64, .lkey = mr->lkey };
struct ibv_send_wr wr = {
    .wr_id = 7, .sg_list = &sge, .num_sge = 1,
    .opcode = IBV_WR_SEND, .send_flags = IBV_SEND_SIGNALED };
struct ibv_send_wr *bad;
if (ibv_post_send(qp, &wr, &bad)) die("post");

struct ibv_wc wc;
int n;
do { n = ibv_poll_cq(cq, 1, &wc); } while (n == 0);
if (n < 0 || wc.status != IBV_WC_SUCCESS) die("completion");
/* only now may buf be reused: wc.wr_id == 7 */

struct ibv_pd *pd = ibv_alloc_pd(ctx);
void *buf = aligned_alloc(4096, 1 << 20);           /* 1 MiB */
struct ibv_mr *mr = ibv_reg_mr(pd, buf, 1 << 20,
        IBV_ACCESS_LOCAL_WRITE | IBV_ACCESS_REMOTE_WRITE |
        IBV_ACCESS_REMOTE_READ);
if (!mr) die("reg_mr");
